31	/// Returned page of thread (thread) summaries.
32	#[derive(Debug, Default, PartialEq)]
33	pub struct ThreadsPage {
34	    /// Thread summaries ordered newest first.
35	    pub items: Vec<ThreadItem>,
36	    /// Opaque pagination token to resume after the last item, or `None` if end.
37	    pub next_cursor: Option<Cursor>,
38	    /// Total number of files touched while scanning this request.
39	    pub num_scanned_files: usize,
40	    /// True if a hard scan cap was hit; consider resuming with `next_cursor`.
41	    pub reached_scan_cap: bool,
42	}
