61	    /// Session source from session metadata.
62	    pub source: Option<SessionSource>,
63	    /// Random unique nickname from session metadata for AgentControl-spawned sub-agents.
64	    pub agent_nickname: Option<String>,
65	    /// Role (agent_role) from session metadata for AgentControl-spawned sub-agents.
66	    pub agent_role: Option<String>,
67	    /// Model provider from session metadata.
