69	    /// CLI version from session metadata.
70	    pub cli_version: Option<String>,
71	    /// RFC3339 timestamp string for when the session was created, if available.
72	    /// created_at comes from the filename timestamp with second precision.
73	    pub created_at: Option<String>,
74	    /// RFC3339 timestamp string for the most recent update (from file mtime).
75	    pub updated_at: Option<String>,
76	}
