135	/// Pagination cursor identifying the timestamp of the last item in a page.
136	#[derive(Debug, Clone, PartialEq, Eq)]
137	pub struct Cursor {
138	    ts: OffsetDateTime,
139	}
140	
141	impl Cursor {
142	    fn new(ts: OffsetDateTime) -> Self {
143	        Self { ts }
144	    }
145	
146	    pub(crate) fn timestamp(&self) -> OffsetDateTime {
147	        self.ts
148	    }
149	}
